import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse(`{"title":"Token Economics","description":"Hearth's budget hierarchy, Token Governor, Context Compiler, model tiers, caching, hard budgets, cost attribution, and default policies.","frontmatter":{"title":"Token Economics","description":"Hearth's budget hierarchy, Token Governor, Context Compiler, model tiers, caching, hard budgets, cost attribution, and default policies.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/token-economics.md","filePath":"en/architecture/token-economics.md","lastUpdated":null}`),o={name:"en/architecture/token-economics.md"};function l(r,e,s,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n(`<p class="eyebrow">TOKEN ECONOMICS</p><h1 id="token-economics" tabindex="-1">Token Economics <a class="header-anchor" href="#token-economics" aria-label="Permalink to &quot;Token Economics&quot;">​</a></h1><p class="lead">The goal is not simply to use fewer tokens, but to make every effective completion cheaper. Tokens are an architectural constraint, not an after-the-fact bill.</p><h2 id="token-economics-1" tabindex="-1">Token Economics <a class="header-anchor" href="#token-economics-1" aria-label="Permalink to &quot;Token Economics&quot;">​</a></h2><p>The goal is not &quot;use fewer tokens,&quot; but &quot;make every effective completion cheaper.&quot; Tokens, cost, latency, and human minutes must be viewed together; you cannot manufacture false savings by lowering quality.</p><h3 id="budget-hierarchy" tabindex="-1">Budget Hierarchy <a class="header-anchor" href="#budget-hierarchy" aria-label="Permalink to &quot;Budget Hierarchy&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Global daily budget</span></span>
<span class="line"><span>  → User/Project budget</span></span>
<span class="line"><span>  → Task budget</span></span>
<span class="line"><span>  → Run budget</span></span>
<span class="line"><span>  → Step budget</span></span>
<span class="line"><span>  → Per-context-injection budget</span></span>
<span class="line"><span>  → Output Token budget</span></span></code></pre></div><p>Budgets include Token, cost, time, tool call count, network requests, and human interruptions. If any tier is exhausted, the system must pause, degrade, or hand off to a human; it must not silently overspend.</p><h3 id="token-governor" tabindex="-1">Token Governor <a class="header-anchor" href="#token-governor" aria-label="Permalink to &quot;Token Governor&quot;">​</a></h3><p>Token Governor is the cross-Executor cost Control Plane:</p><ul><li>Rule-first: Tasks that do not require a model go directly through deterministic paths;</li><li>Task classification: determine Task family, complexity, risk, and privacy level;</li><li>Model catalog: maintain capabilities, price, latency, context, and availability;</li><li>Context Compiler: build the minimal sufficient context;</li><li>Router: select an Executor based on expected success rate/cost;</li><li>Cache: reuse parsing, retrieval, summaries, and verified Artifacts;</li><li>Meter: record input, output, cache, and tool overhead in real time;</li><li>Watchdog: detect abnormal consumption, loops, and budget overruns;</li><li>Attribution: attribute costs to Tasks, projects, skills, and Executors.</li></ul><h3 id="context-compiler" tabindex="-1">Context Compiler <a class="header-anchor" href="#context-compiler" aria-label="Permalink to &quot;Context Compiler&quot;">​</a></h3><p>Context Compiler compresses &quot;everything the system knows&quot; into &quot;the evidence this Task actually needs.&quot; A Context Pack usually contains:</p><ol><li>Goals and acceptance criteria;</li><li>Current Task status;</li><li>Explicit user constraints and preferences;</li><li>Relevant facts and source references;</li><li>Necessary file snippets and Artifact references;</li><li>Available tools and permissions;</li><li>Output schema;</li><li>Budget and deadline;</li><li>Known failures and prohibited paths;</li><li>Questions requiring human decisions.</li></ol><p>Rules:</p><ul><li>Do not use the full chat history as context;</li><li>Do not stuff in entire mailboxes, repositories, or web pages;</li><li>Index, paginate, retrieve, and summarize long material first;</li><li>Keep only assertions with sources;</li><li>Reuse system prompts with stable prefixes and cache-friendly structures;</li><li>Summaries must not lose critical qualifiers, numbers, or references;</li><li>Clean up Working Memory after the Task ends.</li></ul><h3 id="model-and-executor-ladder" tabindex="-1">Model and Executor Ladder <a class="header-anchor" href="#model-and-executor-ladder" aria-label="Permalink to &quot;Model and Executor Ladder&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Capability</th><th>Typical use</th><th>Cost strategy</th></tr></thead><tbody><tr><td>T0 Deterministic</td><td>Rules, SQL, scripts, API, diff</td><td>Filtering, transformation, reconciliation, reading</td><td>No model calls</td></tr><tr><td>T1 Local classifier</td><td>Small models, embedding, rule models</td><td>Classification, priority, entity recognition</td><td>Local, low latency</td></tr><tr><td>T2 Small model</td><td>Short context, structured output</td><td>Summarization, extraction, short drafts</td><td>Usage-based, strict caps</td></tr><tr><td>T3 Native large model</td><td>General reasoning and tools</td><td>Short-chain planning, complex classification</td><td>Medium cost</td></tr><tr><td>T4 Codex</td><td>Long chains, multiple files, complex Artifacts</td><td>Code, research, long documents</td><td>High cost, strong verification</td></tr><tr><td>T5 Human</td><td>Judgment, responsibility, takeover</td><td>High risk, ambiguity, irreversibility</td><td>Scarcest, requires budget</td></tr></tbody></table><p>Routing dynamically selects by Task shape, historical success rate, privacy, and cost, not by tool preference.</p><h3 id="incremental-reading" tabindex="-1">Incremental Reading <a class="header-anchor" href="#incremental-reading" aria-label="Permalink to &quot;Incremental Reading&quot;">​</a></h3><p>Prefer file diff and version comparison, incremental synchronization and cursors, retrieval by page/section/table/row, document indexing and reference location, structured field extraction, summaries of duplicate material, Artifact references, relevant code files and test results, web accessibility trees, and page diff.</p><h3 id="caching-batching-and-local-models" tabindex="-1">Caching, Batching, and Local Models <a class="header-anchor" href="#caching-batching-and-local-models" aria-label="Permalink to &quot;Caching, Batching, and Local Models&quot;">​</a></h3><ul><li>Cache parsing, retrieval, summaries, embedding, and verified Artifacts;</li><li>Do not call large models one by one for low-value Tasks that can be batched and aggregated;</li><li>Prefer local models for privacy-sensitive, low-latency, or offline Tasks;</li><li>Local models are not free: latency, maintenance, and quality costs still count;</li><li>Caches must have versioning, invalidation, and deletion policies; they must not resurrect forgotten content.</li></ul><h3 id="hard-budgets-and-abnormal-stops" tabindex="-1">Hard Budgets and Abnormal Stops <a class="header-anchor" href="#hard-budgets-and-abnormal-stops" aria-label="Permalink to &quot;Hard Budgets and Abnormal Stops&quot;">​</a></h3><ul><li>Each budget tier has a hard limit;</li><li>Loops, repeated tool calls, and abnormal context growth trigger the Watchdog;</li><li>Pause or degrade when the budget is exhausted; do not continue silently;</li><li>Users can see &quot;why this cost so much&quot;;</li><li>Human interruptions are also a cost;</li><li>High-risk Tasks must not skip verification to save budget.</li></ul><h3 id="cost-attribution-and-metrics" tabindex="-1">Cost Attribution and Metrics <a class="header-anchor" href="#cost-attribution-and-metrics" aria-label="Permalink to &quot;Cost Attribution and Metrics&quot;">​</a></h3><ul><li>Cost per Task, project, Executor, model, skill, and user-visible action;</li><li>Verified Success per dollar;</li><li>Token per verified task;</li><li>Joint reduction of human minutes and Token;</li><li>Cache hits, duplicate reads, and invalid retries;</li><li>Abnormal consumption and number of budget stops.</li></ul><h3 id="anti-patterns" tabindex="-1">Anti-patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-patterns&quot;">​</a></h3><ul><li>Optimizing only Token, not human minutes and success rate;</li><li>Using a smaller model and failing repeatedly;</li><li>Stuffing all memory and full text into context;</li><li>Replacing structured extraction with natural-language summaries;</li><li>Unlimited retries;</li><li>Cache pollution;</li><li>Hidden costs;</li><li>Skipping verification or approval to save model calls.</li></ul><h3 id="default-policy" tabindex="-1">Default Policy <a class="header-anchor" href="#default-policy" aria-label="Permalink to &quot;Default Policy&quot;">​</a></h3><ol><li>If rules/scripts can handle it, do not call a model;</li><li>If it can be structured, do not generate natural language;</li><li>If an Artifact can be referenced, do not repeat the full text;</li><li>If a small model can handle it, do not use a large model;</li><li>If it can be cached, do not repeat;</li><li>If you can stop, do not over-retry;</li><li>If it can be handed off to a human, do not run high-risk unattended.</li></ol>`,31)])])}const m=t(o,[["render",l]]);export{p as __pageData,m as default};
